validator:
function validate(input) {
  const [{ Students = [], Subjects = [], Examinations = [] }] = input;
  const students = new Set(), subjects = new Set();
  for (const [id, name] of Students) {
    if (id === null || name === null) return 'Students rows may not contain null.';
    if (students.has(id)) return `student_id ${id} appears twice in Students.`;
    students.add(id);
  }
  for (const [name] of Subjects) {
    if (name === null) return 'subject_name may not be null.';
    // Text compares without case, so 'Math' and 'math' would be the same key.
    if (subjects.has(name.toLowerCase())) return `Subject ${name} appears twice in Subjects.`;
    subjects.add(name.toLowerCase());
  }
  for (const row of Examinations) if (row.some((v) => v === null)) return 'Examinations rows may not contain null.';
  return null;
}

generator:
function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const names = ['Alice', 'Bob', 'John', 'Alex', 'Mia', 'Omar'];
  const subjectPool = ['Programming', 'Math', 'Physics', 'Art', 'Biology', 'Chemistry', 'History', 'Music', 'Geography', 'Economics', 'Latin', 'Drama'];
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const idPool = shuffle(Array.from({ length: small ? 15 : 300 }, (_, i) => i + 1));
  const Students = idPool.slice(0, small ? Math.floor(rand() * 6) : 80).map((id) => [id, small ? pick(names) : `Student ${id}`]);
  const Subjects = shuffle(subjectPool.slice()).slice(0, small ? Math.floor(rand() * 5) : 12).map((name) => [name]);
  const Examinations = [];
  const rows = small ? Math.floor(rand() * 9) : 2000;
  for (let i = 0; i < rows; i++) {
    // Mostly real pairs (with repeats); now and then a student or subject that is not listed.
    const student = Students.length && rand() < 0.9 ? pick(Students)[0] : 900 + Math.floor(rand() * 3);
    const subject = Subjects.length && rand() < 0.9 ? pick(Subjects)[0] : 'Astronomy';
    Examinations.push([student, subject]);
  }
  return [{ Students, Subjects, Examinations }];
}
